from taf.nms.nom.schemas.base import SchemaField, SchemaObject, SchemaObjects
from taf.nms.nom.schemas.operations.operation_execution import OperationExecutionWindowResponse


class OperationScheduleTypeResponse(SchemaObject):
    date_time = SchemaField(name="date_time")
    start_time = SchemaField(name="start_time")
    start_date = SchemaField(name="start_date")
    end_date = SchemaField(name="end_date")
    days_of_week = SchemaField(name="days_of_week")
    time_zone = SchemaField(name="time_zone")

    def __init__(self, date_time, start_time, start_date, end_date, days_of_week, time_zone):
        self.date_time = date_time
        self.start_time = start_time
        self.start_date = start_date
        self.end_date = end_date
        self.days_of_week = days_of_week
        self.time_zone = time_zone

        super(OperationScheduleTypeResponse, self).__init__()


class OperationScheduledResponse(SchemaObject):
    operation_attributes = SchemaField(name="operation_attributes")
    user_defined_name = SchemaField(name="user_defined_name")
    user_defined_description = SchemaField(name="user_defined_description")
    execution_window = SchemaField(name="execution_window", klass=OperationExecutionWindowResponse)
    operation_name = SchemaField(name="operation_name")
    schedule = SchemaField(name="schedule", klass=OperationScheduleTypeResponse)
    schedule_id = SchemaField(name="schedule_id")
    user_name = SchemaField(name="user_name")
    next_execution = SchemaField(name="next_execution")

    def __init__(self, operation_attributes, user_defined_name, user_defined_description,
                 execution_window, operation_name, schedule, schedule_id, user_name, next_execution):
        self.operation_attributes = operation_attributes
        self.user_defined_name = user_defined_name
        self.user_defined_description = user_defined_description
        self.execution_window = execution_window
        self.operation_name = operation_name
        self.schedule = schedule
        self.schedule_id = schedule_id
        self.user_name = user_name
        self.next_execution = next_execution

        super(OperationScheduledResponse, self).__init__()


class OperationScheduledResponses(SchemaObjects):
    schema = OperationScheduledResponse
